import { finding } from '../../engine/checks/helpers/findings.mjs';

// The check behind the repo-hygiene rule that a build/tooling artifact never
// becomes a tracked file. The grounded case is a `git add -A` run in the same
// change that dropped the artifact's `.gitignore` lines: the ignore rules go,
// the artifacts the previous runs left in the worktree are suddenly no longer
// ignored, and the bulk add sweeps them into the very commit meant to remove
// them — a valid commit, green tests, and nothing but an inflated file count to
// show for it.
//
// The pattern set is deliberately confined to compiler caches, test-runner
// caches and OS turds — artifacts no project tracks on purpose — so the check
// stays inert on anything a repo might legitimately vendor (node_modules, a
// checked-in dist/). Advisory rather than blocking: the fix is a deletion, and a
// pre-existing artifact in a member repo should surface as a finding to clear,
// not as a red sweep that blocks that repo's maintenance.
const ARTIFACTS = [
  { re: /(^|\/)__pycache__\//, what: 'a Python bytecode cache directory' },
  { re: /\.py[co]$/, what: 'a compiled Python file' },
  { re: /(^|\/)\.pytest_cache\//, what: 'a pytest cache directory' },
  { re: /(^|\/)\.mypy_cache\//, what: 'a mypy cache directory' },
  { re: /(^|\/)\.ruff_cache\//, what: 'a ruff cache directory' },
  { re: /(^|\/)[^/]+\.egg-info\//, what: 'a Python packaging metadata directory' },
  { re: /(^|\/)\.DS_Store$/, what: 'a macOS Finder metadata file' },
  { re: /(^|\/)Thumbs\.db$/, what: 'a Windows Explorer thumbnail cache' },
];

const rule = {
  id: 'committed-build-artifact',
  severity: 'advisory',
  description: 'A build, cache or OS artifact must not be a tracked file',
  doc: 'packs/git-github/skills/git-github-advanced/SKILL.md',
  why: 'these are regenerated on demand, so tracking one only adds churn and diff noise — and the usual way one lands is a bulk `git add -A` after its .gitignore rules were removed',

  run(ctx) {
    return ctx.files.flatMap((f) => {
      const hit = ARTIFACTS.find((a) => a.re.test(f));
      if (!hit) return [];
      return [finding(rule, {
        file: f,
        what: `${hit.what} is tracked in git`,
        fix: `delete it from the worktree (or \`git rm -r --cached\` it) and keep its .gitignore rule — never drop an ignore rule while the artifacts it covered are still on disk, and read \`git diff --cached --stat\` after any bulk \`git add -A\``,
      })];
    });
  },
};

export default rule;

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRepo, cleanup } from '../../engine-tests/helpers.mjs';
import { buildContext } from '../../engine/checks/helpers/repo-context.mjs';
import rule from '../../packs/basics/committed-build-artifact.mjs';

const run = (files) => {
  const root = makeRepo({ changed: files });
  try { return rule.run(buildContext({ root, mode: 'all' })); } finally { cleanup(root); }
};

test('committed-build-artifact: a clean tree yields no findings', () => {
  assert.deepEqual(run({
    'src/app.py': 'print("hi")\n',
    'src/lib/thing.mjs': 'export const x = 1;\n',
    '.gitignore': '__pycache__/\n*.pyc\n',
  }), []);
});

test('committed-build-artifact: flags a swept-in Python bytecode cache', () => {
  const f = run({ 'src/__pycache__/app.cpython-312.pyc': 'x\n' });
  assert.equal(f.length, 1);
  assert.match(f[0].what, /Python bytecode cache directory is tracked/);
  assert.match(f[0].fix, /git add -A/);
});

test('committed-build-artifact: flags tool caches and OS turds', () => {
  const files = run({
    '.pytest_cache/v/cache/lastfailed': '{}\n',
    '.mypy_cache/3.12/x.json': '{}\n',
    'docs/.DS_Store': 'x\n',
    'docs/Thumbs.db': 'x\n',
    'pkg.egg-info/PKG-INFO': 'Name: pkg\n',
  }).map((x) => x.file).sort();
  assert.deepEqual(files, [
    '.mypy_cache/3.12/x.json',
    '.pytest_cache/v/cache/lastfailed',
    'docs/.DS_Store',
    'docs/Thumbs.db',
    'pkg.egg-info/PKG-INFO',
  ]);
});

// Narrowness: the set is confined to artifacts no project tracks on purpose, so
// a repo that deliberately vendors a dependency or a built bundle stays silent.
test('committed-build-artifact: stays quiet on deliberately vendored trees', () => {
  assert.deepEqual(run({
    'node_modules/left-pad/index.js': 'module.exports = 1;\n',
    'dist/bundle.js': 'var a=1;\n',
    'build/app.wasm': 'x\n',
    'src/pycache_notes.md': 'about __pycache__ handling\n',
  }), []);
});

