import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { discoverPacks } from '../engine/pack_loader/pack-registry.mjs';
import { packRules } from '../engine/checks/run-active-pack-rules.mjs';

// packs/README.md's corpus tally quotes how many hardcoded checks the canon
// carries — a derived number that was hand-maintained and drifted badly (it
// read 41 while the runner listed 65, so the ratio it argues from was wrong by
// a third). The catalog is the single source of truth; this guard keeps the
// prose equal to it. `packRules` is the same assembly `--list` prints, so the
// tally can never disagree with the runner about what a rule is.
//
// Deliberately guards only the CHECK count. The prose-rule figures beside it
// are audit estimates from docs/conversion-inventory.md — nothing derives them,
// so the README marks them as a dated snapshot rather than pretending they are
// live, and no test can hold them honest.
const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CATALOG = 'packs/README.md';
const TALLY = /\|\s*\*\*Hardcoded conformance checks\*\*\s*\|\s*\*\*(\d+)\*\*/;

test('the packs/ catalog tally equals the rule catalog the runner lists', async () => {
  const { packs } = await discoverPacks({ localRoot: ROOT });
  const actual = packRules(packs).length;

  const readme = readFileSync(join(ROOT, CATALOG), 'utf8');
  const m = TALLY.exec(readme);
  assert.ok(m, `${CATALOG} carries no parseable "Hardcoded conformance checks" tally — keep the bolded count in the corpus-tally table so this guard can read it`);
  assert.equal(
    Number(m[1]), actual,
    `${CATALOG} says ${m[1]} hardcoded checks; the catalog carries ${actual}. Update the tally (and the ratio it feeds) in the same change that adds or removes a rule.`
  );
});

// The write-surface gate for the growth PROMOTE stage (tasks/growth-promote/, this pack).
//
// Promote's write surface is bounded to the shared canon's two homes — packs/
// and skills/. This module is the GUARANTEE: any changed path outside packs/ or
// skills/ fails the gate. The promote AGENT never runs it and needn't know it
// exists — CI runs it automatically on the promote PR (checks-ci.yml, gated on
// the growth-promote branch prefix). The corpus principle it enforces: prose is
// a request; the post-hoc diff check is the guarantee.
//
// Why CI branch-gates it instead of registering it as a pack/skill check that
// runs on every PR: the "packs/skills only" boundary is true for PROMOTE alone —
// an ordinary engine change legitimately edits checks/, engine/, … Nothing in
// the tree marks a diff as a promote run, so no always-on check could self-gate
// to promote; the promote PR's branch prefix is the signal CI keys on.
import { buildContext } from '../../../../engine/checks/helpers/repo-context.mjs';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';

const inBounds = (p) => p.startsWith('packs/') || p.startsWith('skills/');

const rule = {
  id: 'promote-scope',
  severity: 'blocking',
  description: 'The growth promote stage writes only under packs/ or skills/',
  doc: '.claudinite/local/packs/canon-curation/tasks/growth-promote/task.md',
  why: 'promote runs unattended with a fleet-wide token; a write outside the canon homes escapes the review-by-blast-radius boundary the growth lifecycle is built on',

  // Every path the branch touches vs the merge-base — added/modified/untracked
  // (allFiles in changed mode) plus deletions — that is not under packs/ or
  // skills/ is one finding. No merge-base ⇒ no diff to scope ⇒ nothing to certify;
  // the CLI wrapper treats that as a hard refusal rather than a silent pass.
  run(ctx) {
    if (!ctx.mergeBase) return [];
    const touched = [...new Set([...ctx.allFiles, ...ctx.deleted])];
    return touched
      .filter((p) => !inBounds(p))
      .sort()
      .map((p) =>
        finding(rule, {
          file: p,
          what: `the promote phase touched ${p}, outside packs/ and skills/`,

